using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using ProjectWait.M.Elevator;public static class InspectCoping {public static string Main(){var l=UnityEngine.Object.FindFirstObjectByType<ElevatorLesson>();var data=new{scene=SceneManager.GetActiveScene().path,playing=Application.isPlaying,cameraParent=l.playerCamera.transform.parent.name,bones=l.friend.GetComponentsInChildren<Transform>(true).Where(t=>new[]{"head","foot.L","foot.R","thigh.L","shin.L","pelvis"}.Contains(t.name)).Select(t=>new{name=t.name,pos=t.position.ToString("F4"),local=t.localPosition.ToString("F4"),rot=t.rotation.eulerAngles.ToString(),scale=t.lossyScale.ToString()}).ToArray(),renderers=l.friend.GetComponentsInChildren<Renderer>(true).Where(r=>!r.name.StartsWith("SkyGlow")).Select(r=>new{name=r.name,type=r.GetType().Name,centre=r.bounds.center.ToString("F4"),size=r.bounds.size.ToString("F4"),materials=r.sharedMaterials.Select(m=>m?m.name:"").ToArray()}).ToArray()};var json=Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented);File.WriteAllText("Assets/M/CodexTemp/ElevatorCoping_20261030~/BeforeScene.json",json);return json;}}